mapper.select:
SELECT a.device_id AS deviceId, MAX(a.device_name) AS deviceName, MAX(a.device_ip) AS deviceIp, COUNT(1) AS faultCount, SUM(CASE WHEN a.alarm_level = 'URGENT' THEN 1 ELSE 0 END) AS urgentCount, IFNULL(SUM(a.duration_minutes), 0) AS totalMinutes FROM alarm_record a WHERE a.alarm_type = 'OFFLINE'
AND a.alarm_time >= #{start}
AND a.alarm_time < #{end}
GROUP BY a.device_id ORDER BY faultCount DESC, urgentCount DESC LIMIT #{limit}
